package cn.edu.njupt.studycheckin;

import android.content.*;
import android.graphics.BitmapFactory;
import android.graphics.Bitmap;
import android.graphics.Canvas;
import android.graphics.Paint;
import android.graphics.LinearGradient;
import android.graphics.Shader;
import android.net.Uri;
import android.util.AtomicFile;
import android.util.Base64;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.concurrent.*;
import java.util.zip.*;

/** Storage/concurrency/migration tests run on Android, not copies of the UI implementation. */
public final class InspirationTests {
    private static void check(boolean b,String m,List<String> passes)throws Exception{if(!b)throw new Exception("FAIL: "+m);passes.add(m);}
    private static JSONObject fresh()throws Exception{return new JSONObject().put("version",1).put("cards",new JSONObject()).put("events",new JSONArray()).put("daily",new JSONObject()).put("imageUse",new JSONObject()).put("textUse",new JSONObject()).put("settings",new JSONObject().put("online",false)).put("lastFetchAt","").put("lastFetchMessage","");}
    // Synthetic bitmap fixtures are compiled ONLY into the test APK, never the release or its images.
    private static void candidateFixtures(Context c)throws Exception{for(int i=0;i<3;i++){Bitmap b=Bitmap.createBitmap(600,400,Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);Paint paint=new Paint();paint.setShader(new LinearGradient(0,0,600,400,0xff506070+i*0x172819,0xffabcdbf-i*0x121418,Shader.TileMode.CLAMP));canvas.drawRect(0,0,600,400,paint);ByteArrayOutputStream out=new ByteArrayOutputStream();b.compress(Bitmap.CompressFormat.PNG,100,out);b.recycle();byte[] bytes=out.toByteArray();String hash=InspirationStore.hash(bytes);InspirationStore.writeMedia(c,hash+".png",bytes);JSONObject card=InspirationStore.baseCard("fixture_"+i,"测试候选文字 "+i,"zh","","测试").put("imageKey",hash+".png").put("imageHash",hash).put("imageId","picsum:"+(90000+i)).put("imageSource","test fixture").put("imageAuthor","").put("imageTitle","fixture").put("imagePage","").put("imageLicense","test only").put("textId","fixture-text-"+i).put("textSource","test fixture").put("textAuthor","").put("textPage","").put("textLicense","test only").put("translationSource","").put("origin","online");InspirationStore.addCandidate(c,card);}}
    public static void run(Context c,List<String> checks)throws Exception{
        JSONObject original=InspirationStore.load(c),study=DataStore.load(c);ByteArrayOutputStream preserved=new ByteArrayOutputStream();BackupManager.export(c,preserved);byte[] preservedBackup=preserved.toByteArray();try{
            InspirationStore.save(c,fresh());
            boolean noImage=false;try{InspirationStore.record(c,"daily","2026-10-13");}catch(InspirationStore.NoImageException e){noImage=true;}check(noImage&&InspirationStore.load(c).getJSONObject("daily").length()==0,"no downloaded image means no draw and no consumed chance",checks);
            candidateFixtures(c);
            check(InspirationStore.textHash(" A b C ！").equals(InspirationStore.textHash("abc")),"text dedup normalizes spacing/case/punctuation",checks);
            JSONObject start=InspirationStore.record(c,"startup","2026-10-13"),first=InspirationStore.record(c,"daily","2026-10-13");
            check(!first.getBoolean("imageRepeat")&&!first.getBoolean("textRepeat"),"daily image and text both avoid startup history",checks);
            check(!start.getJSONObject("card").getString("imageHash").equals(first.getJSONObject("card").getString("imageHash")),"new daily illustration differs from startup",checks);
            check(InspirationStore.record(c,"daily","2026-10-13").getString("id").equals(first.getString("id")),"same calendar date reuses fixed daily card",checks);
            check(InspirationStore.load(c).getJSONArray("events").length()==2,"repeated daily draw does not consume new content",checks);
            check(DataStore.load(c).toString().equals(study.toString()),"daily cards never rewrite existing study state",checks);
            ExecutorService workers=Executors.newFixedThreadPool(6);List<Future<String>> jobs=new ArrayList<>();for(int i=0;i<6;i++)jobs.add(workers.submit(()->InspirationStore.record(c,"daily","2026-10-14").getString("id")));Set<String> ids=new HashSet<>();for(Future<String> f:jobs)ids.add(f.get());workers.shutdown();
            check(ids.size()==1&&InspirationStore.load(c).getJSONObject("daily").length()==2,"concurrent daily draws commit exactly once",checks);
            JSONObject next=InspirationStore.getEntry(c,ids.iterator().next());check(!next.getJSONObject("card").getString("textHash").equals(first.getJSONObject("card").getString("textHash")),"next date gets a different text",checks);
            InspirationStore.favorite(c,first.getString("id"),true);check(InspirationStore.snapshot(c,"favorites",0,20).getInt("total")==1,"favorite appears in separate history",checks);
            JSONObject collision=new JSONObject(first.getJSONObject("card").toString()).put("id","duplicate_image_candidate").put("text","测试新的文字，但相同图片不能绕过去重。");collision.put("textHash",InspirationStore.textHash(collision.getString("text")));InspirationStore.addCandidate(c,collision);
            JSONObject chosen=InspirationStore.record(c,"daily","2026-10-15");check(!chosen.getJSONObject("card").getString("id").equals("duplicate_image_candidate"),"re-pairing same image cannot bypass separate dedup",checks);
            int count=InspirationStore.load(c).getJSONArray("events").length();InspirationStore.cleanPending(c);check(InspirationStore.load(c).getJSONArray("events").length()==count&&InspirationStore.getEntry(c,first.getString("id")).getJSONObject("card").getBoolean("favorite"),"cache cleanup preserves histories/favorites",checks);
            JSONObject bad=new JSONObject(first.getJSONObject("card").toString()).put("language","en").put("translation","");boolean rejected=false;try{InspirationStore.validateCard(bad);}catch(Exception e){rejected=true;}check(rejected,"untranslated foreign card is rejected before draw",checks);
            bad=new JSONObject(first.getJSONObject("card").toString()).put("imageKey","../../study-state.json");rejected=false;try{InspirationStore.validateCard(bad);}catch(Exception e){rejected=true;}check(rejected,"card media paths cannot escape private image directory",checks);
            byte[] imageBytes=InspirationStore.read(new FileInputStream(InspirationStore.media(c,first.getJSONObject("card").getString("imageKey"))),InspirationStore.MAX_IMAGE_BYTES);check(ImageChecks.validate(imageBytes).equals("png"),"downloaded image checks actual format and decoding",checks);rejected=false;try{ImageChecks.validate(Arrays.copyOf(imageBytes,imageBytes.length-12));}catch(Exception e){rejected=true;}check(rejected,"truncated image rejected before becoming a candidate",checks);
            JSONArray library=new JSONArray(new String(InspirationStore.read(c.getAssets().open("inspiration-library.json"),2*1024*1024),StandardCharsets.UTF_8));int foreign=0;for(int i=0;i<library.length();i++){JSONObject t=library.getJSONObject(i);if(t.has("language")){foreign++;check(!t.optString("translation").isEmpty(),"original foreign card "+i+" has Chinese meaning",checks);}}check(foreign>=20,"offline library covers multiple foreign languages",checks);
            JSONObject complete=InspirationStore.load(c);ByteArrayOutputStream output=new ByteArrayOutputStream();BackupManager.export(c,output);byte[] backup=output.toByteArray();check(backup[0]=='P'&&backup[1]=='K',"complete backup is an actual ZIP with media",checks);
            InspirationStore.save(c,fresh());try(BackupManager.Imported imported=BackupManager.read(c,new ByteArrayInputStream(backup))){check(imported.complete(),"complete ZIP is recognized",checks);BackupManager.restore(c,imported);}
            check(InspirationStore.load(c).toString().equals(complete.toString()),"ZIP restore preserves card/history/favorite/dedup metadata",checks);
            check(InspirationStore.media(c,first.getJSONObject("card").getString("imageKey")).isFile(),"ZIP restore retains actual history image",checks);
            JSONObject studyRestored=DataStore.load(c);studyRestored.remove("_revision");JSONObject studyBefore=new JSONObject(study.toString());studyBefore.remove("_revision");check(studyRestored.toString().equals(studyBefore.toString()),"ZIP restore preserves original learning fields",checks);
            try(BackupManager.Imported imported=BackupManager.read(c,new ByteArrayInputStream(study.toString().getBytes(StandardCharsets.UTF_8)))){check(!imported.complete(),"legacy v1 JSON remains importable",checks);BackupManager.restore(c,imported);}check(InspirationStore.load(c).toString().equals(complete.toString()),"legacy JSON import leaves card library and favorites intact",checks);
            output=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(output)){z.putNextEntry(new ZipEntry("../study-state.json"));z.write("{}".getBytes(StandardCharsets.UTF_8));z.closeEntry();}rejected=false;try{BackupManager.read(c,new ByteArrayInputStream(output.toByteArray()));}catch(Exception e){rejected=true;}check(rejected,"ZIP traversal rejected without writing user records",checks);
            output=new ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(output)){z.putNextEntry(new ZipEntry("media/"+first.getJSONObject("card").getString("imageKey")));z.write(new byte[]{1,2,3});z.closeEntry();}rejected=false;try{BackupManager.read(c,new ByteArrayInputStream(output.toByteArray()));}catch(Exception e){rejected=true;}check(rejected,"corrupted ZIP image digest rejected",checks);
            byte[] previous=InspirationStore.read(new FileInputStream(new File(c.getFilesDir(),"study-state.json")),DataStore.MAX_BYTES);byte[] previousCards=InspirationStore.load(c).toString().getBytes(StandardCharsets.UTF_8);JSONObject journal=new JSONObject().put("study",Base64.encodeToString(previous,Base64.NO_WRAP)).put("inspiration",Base64.encodeToString(previousCards,Base64.NO_WRAP));File journalFile=new File(c.getFilesDir(),"restore-journal.json");try(OutputStream out=new FileOutputStream(journalFile)){out.write(journal.toString().getBytes(StandardCharsets.UTF_8));}InspirationStore.save(c,fresh());BackupManager.recover(c);check(InspirationStore.load(c).toString().equals(new String(previousCards,StandardCharsets.UTF_8))&&!journalFile.exists(),"interrupted two-file restore rolls back from recovery journal",checks);
            JSONObject longCard=new JSONObject(first.getJSONObject("card").toString()).put("id","long_text_test");StringBuilder longText=new StringBuilder();for(int i=0;i<90;i++)longText.append("完整内容第").append(i+1).append("段：这一段应在长图里保留，不通过缩小字号或截断来省略。\n");longText.append("FINAL_TEXT_SENTINEL_完整结尾");longCard.put("text",longText.toString()).put("textHash",InspirationStore.textHash(longText.toString())).put("translation","").put("language","zh");JSONObject s=InspirationStore.load(c);s.getJSONObject("cards").put("long_text_test",longCard);s.getJSONArray("events").put(new JSONObject().put("id","poster_long_test").put("cardId","long_text_test").put("kind","startup").put("date","2026-10-13").put("at",java.time.Instant.now().toString()).put("imageRepeat",true).put("textRepeat",false));InspirationStore.save(c,s);
            ArrayList<File> pages=InspirationPoster.render(c,"poster_long_test");check(pages.size()>1,"long text poster splits into multiple readable images",checks);for(File page:pages){BitmapFactory.Options opts=new BitmapFactory.Options();opts.inJustDecodeBounds=true;BitmapFactory.decodeFile(page.getPath(),opts);check(opts.outWidth==1080&&opts.outHeight<=3900,"poster page dimensions fit bounded memory",checks);}Intent share=InspirationPoster.share(c,pages,"poster_long_test");Intent inner=share.getParcelableExtra(Intent.EXTRA_INTENT);check(inner.getAction().equals(Intent.ACTION_SEND_MULTIPLE)&&(inner.getFlags()&Intent.FLAG_GRANT_READ_URI_PERMISSION)!=0&&inner.getClipData().getItemCount()==pages.size(),"long posters share all pages with temporary read grants",checks);
            CardShareProvider provider=new CardShareProvider();android.content.pm.ProviderInfo info=new android.content.pm.ProviderInfo();info.authority=c.getPackageName()+".cards";provider.attachInfo(c,info);Uri valid=Uri.parse("content://"+info.authority+"/"+pages.get(0).getName());check(provider.openFile(valid,"r").getStatSize()>0,"share provider opens only generated poster",checks);rejected=false;try{provider.openFile(Uri.parse("content://"+info.authority+"/study-state.json"),"r");}catch(FileNotFoundException e){rejected=true;}check(rejected,"share provider refuses private study file",checks);rejected=false;try{provider.openFile(valid,"w");}catch(FileNotFoundException e){rejected=true;}check(rejected,"share provider rejects writes",checks);
            check(InspirationSources.refresh(c).contains("关闭"),"offline mode does not request remote materials",checks);
        }finally{try(BackupManager.Imported imported=BackupManager.read(c,new ByteArrayInputStream(preservedBackup))){BackupManager.restore(c,imported);}DataStore.restore(c,study);}
    }
}
